/* CrossFit DNA — forged dark steel, red intensity, stencil grit, affiliate blue */
.theme-crossfit-dna {
  --bg: oklch(0.218 0 0);
  --surface: oklch(0.260 0 0);
  --surface-2: oklch(0.301 0 0);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.648 0.007 286.2);
  --accent: oklch(0.520 0.201 28.0);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.499 0.179 257.9);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.520 0.201 28.0);
  --radius: 2px;
  --radius-sm: 1px;
  --radius-lg: 3px;
  --radius-pill: 3px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Black Ops One", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.03em;
  --label-transform: uppercase;
  --label-tracking: 0.16em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-crossfit-dna h1,
.theme-crossfit-dna h2,
.theme-crossfit-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-crossfit-dna { background-image: repeating-linear-gradient(45deg, oklch(1 0 0 / 2%) 0 2px, transparent 2px 8px); }
.theme-crossfit-dna h1, .theme-crossfit-dna h2 { text-transform: uppercase; }
.theme-crossfit-dna button { text-transform: uppercase; letter-spacing: 0.1em; font-weight: 700; }
.theme-crossfit-dna button:active { transform: scale(0.97); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
